from .core import (CONTENT, SITE, UPDATED, breadcrumb, build_challenge, faq, learning_schema, lesson_header, page, quick_answer, takeaways)


def build():
    slug='context-window';d=CONTENT['lessons'][slug]
    context_body=f'''<div class="container">{lesson_header(slug,'▱')}{quick_answer(d['quick'])}<div class="lesson-grid"><div><section class="card interactive"><div class="panel-title"><span>Context usage</span><span class="context-usage">191,250 / 200,000 tokens</span></div><div class="context-bar"><span class="seg-system" style="width:12%"></span><span class="seg-convo" style="width:42%"></span><span class="seg-docs" style="width:28%"></span><span class="seg-tools" style="width:12%"></span><span class="seg-memory" style="width:6%"></span></div><div class="subtle">System 12% · Conversation 42% · Documents 28% · Tools 12% · Memory 6%</div><div class="demo-subtitle">Choose a strategy</div><div class="strategy-row"><button type="button" class="strategy" data-strategy="drop">Drop old messages</button><button type="button" class="strategy active" data-strategy="summarize">Summarize</button><button type="button" class="strategy" data-strategy="rag">RAG</button><button type="button" class="strategy" data-strategy="memory">Memory</button></div><div class="compare-grid"><div class="compare-card warn"><span class="label">Before</span><strong>191,250 / 200,000</strong><div class="bar" style="margin-top:10px"><span style="width:96%;background:var(--warning)"></span></div><p class="subtle">Risk: little space remains for new turns.</p></div><span class="flow-arrow">→</span><div class="compare-card good"><span class="label">After strategy</span><strong><span data-after-count>112,430</span> / 200,000</strong><div class="bar" style="margin-top:10px"><span data-after-bar style="width:56%"></span></div><p class="subtle" data-after-note>78,820 tokens condensed or removed; 87,570 tokens of headroom remain.</p></div></div><div class="note" style="margin-top:15px">Context engineering is trade-off management: keep the most useful information available while controlling cost, latency, and information loss.</div></section>{takeaways([('Context is finite','Inputs compete for a limited working budget.'),('Summaries compress history','They preserve less detail but free capacity.'),('RAG retrieves on demand','External knowledge need not stay in context.'),('Memory is a separate layer','Persistent facts are not the same as active context.')])}{build_challenge('Design a context strategy for a support agent','Decide what stays in the prompt, what becomes a summary, what goes to retrieval, and what belongs in persistent memory.')}</div><aside class="lesson-sidebar"><div class="card side-card"><h3>What you’ll learn</h3><ul class="check-list"><li>What consumes context</li><li>Why overflow happens</li><li>Trade-offs of four strategies</li></ul></div><div class="card side-card"><h3>Lesson path</h3><ol class="steps"><li class="done"><span class="step-num">1</span><div><b>Fill</b><div class="subtle">Add system + history</div></div><span>✓</span></li><li class="done"><span class="step-num">2</span><div><b>Observe</b><div class="subtle">Watch token usage</div></div><span>✓</span></li><li class="active"><span class="step-num">3</span><div><b>Manage</b><div class="subtle">Choose a strategy</div></div></li><li><span class="step-num">4</span><div><b>Compare</b><div class="subtle">Inspect trade-offs</div></div></li></ol></div></aside></div><section class="card section-explainer"><span class="eyebrow">Concept guide</span><h2>What is an LLM context window?</h2><p>A context window is the finite amount of input information a model can process for a generation step. System instructions, user and assistant messages, retrieved passages, tool outputs, and other supplied content all consume that working budget.</p><h3>What happens when context becomes too large?</h3><p>An application must decide what to remove, compress, retrieve later, or persist elsewhere. The correct choice depends on which information is important for the next model decision.</p><h3>How is RAG different from memory?</h3><p>RAG retrieves relevant external information when needed. Memory usually refers to information persisted across turns or sessions. Both can supply context, but neither is identical to the context window itself.</p><h3>Why is context engineering important?</h3><p>Good context design improves relevance and reliability while helping control token cost and latency. More context is not automatically better context.</p><h3>Common questions</h3>{faq([('Is context the same as memory?','No. Context is the current working input; memory is a persistence strategy that may later supply context.'),('Does RAG increase the context window size?','No. RAG selects information to place inside the available context.'),('Should I always summarize old messages?','No. Summarization trades detail for compactness and can remove information that later becomes important.'),('Are the token limits shown here model-specific?','The 200,000-token value is an educational example, not a claim about every model.')])}<div class="references"><strong>SeeAI learning note</strong> · Reviewed {UPDATED}. The lab uses a stable simulated token budget to make trade-offs observable.</div></section><section class="card next-band"><div><strong>You can now reason about context trade-offs.</strong><div class="subtle">Next: see how agents use tools and observations in a loop.</div></div><a class="btn primary" data-event="lesson_next_clicked" href="/en/lessons/agent-loop/">Continue →</a></section></div>'''
    (SITE/f'en/lessons/{slug}/index.html').write_text(page(f"{d['name']} — Context engineering visual lab | SeeAI",d['description'],f'/en/lessons/{slug}/',context_body,active='Lessons',schemas=[learning_schema(slug),breadcrumb([('SeeAI','/en/'),('Lessons','/en/#lessons'),(d['name'],f'/en/lessons/{slug}/')])],scripts='<script src="/assets/context.js" defer></script>'),encoding='utf-8')
